def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def edge_bar(horizontal, edge):
        n = w if horizontal else h
        if horizontal:
            coords = [(0, i) if edge == 0 else (h - 1, i) for i in range(n)]
        else:
            coords = [(i, 0) if edge == 0 else (i, w - 1) for i in range(n)]
        colors = [grid[r][c] for r, c in coords if grid[r][c] != background]
        if not colors:
            return None
        color = max(set(colors), key=colors.count)
        positions = [i for i, (r, c) in enumerate(coords) if grid[r][c] == color]
        if not positions or positions != list(range(min(positions), max(positions) + 1)):
            return None
        return color, min(positions), max(positions) + 1

    for horizontal in (True, False):
        bars = (edge_bar(horizontal, 0), edge_bar(horizontal, 1))
        if not all(bars) or bars[0][0] != bars[1][0]:
            continue
        border_color = bars[0][0]
        markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
                   if grid[r][c] != background and grid[r][c] != border_color]
        for r, c, color in markers:
            pos = c if horizontal else r
            source = next((i for i, (_, lo, hi) in enumerate(bars)
                           if lo <= pos < hi), None)
            if source is None:
                continue
            source_lo = bars[source][1]
            opposite_lo, opposite_hi = bars[1 - source][1:]
            mapped = opposite_lo + pos - source_lo
            if mapped >= opposite_hi:
                continue

            # Continue from the edge bar along the marker's coordinate and
            # recolor the marker as the ray endpoint.
            if horizontal:
                edge_r, step = (0, 1) if source == 0 else (h - 1, -1)
                rr = edge_r + step
                while 0 <= rr < h:
                    if (rr, c) == (r, c):
                        out[rr][c] = 4
                        break
                    if grid[rr][c] == background:
                        out[rr][c] = color
                    rr += step

                # Matching position in the opposite bar projects through the
                # interior only; the boundary bars themselves remain unchanged.
                for rr in range(1, h - 1):
                    if grid[rr][mapped] == background:
                        out[rr][mapped] = color
            else:
                edge_c, step = (0, 1) if source == 0 else (w - 1, -1)
                cc = edge_c + step
                while 0 <= cc < w:
                    if (r, cc) == (r, c):
                        out[r][cc] = 4
                        break
                    if grid[r][cc] == background:
                        out[r][cc] = color
                    cc += step

                other_edge_c, other_step = (0, 1) if source == 1 else (w - 1, -1)
                cc = other_edge_c + other_step
                while 0 <= cc < w:
                    if grid[mapped][cc] == background:
                        out[mapped][cc] = color
                    cc += other_step
        return out
    return out

